const BEGIN = '<<<<<<< begin '
const SEP = '======= begin '
const END = '>>>>>>> end conflict'

function segHead (ln) {
  const head = ln.startsWith(BEGIN) ? ln.slice(BEGIN.length) : ln.slice(SEP.length)
  const sp = head.indexOf(' ')
  return sp === -1 ? [head, ''] : [head.slice(0, sp), head.slice(sp + 1)]
}

export function unionReply (hunksText) {
  const lines = String(hunksText || '').split('\n')
  const blocks = []
  let i = 0
  let curId = null
  let inConflict = false
  let segs = null
  while (i < lines.length) {
    const ln = lines[i]
    const m = /^HUNK (\S+) lines/.exec(ln)
    if (m) {
      curId = m[1]
      inConflict = false
      segs = []
    } else if (ln === '--- conflict') {
      inConflict = true
    } else if (inConflict && (ln.startsWith(BEGIN) || ln.startsWith(SEP))) {
      const [kind] = segHead(ln)
      segs.push({ kind, lines: [] })
    } else if (inConflict && ln === END) {
      blocks.push({ id: curId, segs })
      inConflict = false
    } else if (inConflict && segs && segs.length) {
      segs[segs.length - 1].lines.push(ln)
    }
    i++
  }
  if (!blocks.length) return null
  const hunks = []
  for (const b of blocks) {
    if (b.segs.some((s) => s.kind === 'deleted')) return null
    const content = b.segs.filter((s) => s.kind === 'added').flatMap((s) => s.lines).join('\n')
    hunks.push({ id: b.id, content })
  }
  return { hunks }
}
